'use client';

import Link from 'next/link';

const SCHOOL_LOGO = '/school-logo.png';

export default function PublicHome() {
  return (
    <main className="public-home">
      <nav className="public-nav" aria-label="Public navigation">
        <Link className="public-brand" href="/" aria-label="Alumni Meet home">
          <span className="public-brand-mark"><img src={SCHOOL_LOGO} alt="" /></span>
          <span><strong>Alumni</strong><small>Meet</small></span>
        </Link>
        <div className="public-nav-links">
          <a href="#about">About</a>
          <a href="#community">Community</a>
          <Link className="public-login" href="/login">Log in</Link>
          <Link className="public-register" href="/register">Register <span aria-hidden="true">↗</span></Link>
        </div>
      </nav>

      <section className="public-hero" id="about">
        <div className="public-hero-copy">
          <p className="public-kicker">ST. PHILOMENA'S HIGH SCHOOL · ALUMNI ASSOCIATION</p>
          <h1>Old hallways.<br /><em>New chapters.</em></h1>
          <p className="public-intro">A place for the people who made school memorable. Reconnect with classmates, discover what is happening, and keep the community close.</p>
          <div className="public-hero-actions">
            <Link className="public-primary-button" href="/register">Join the community <span aria-hidden="true">↗</span></Link>
            <Link className="public-text-link" href="/login">Already a member? Log in</Link>
          </div>
        </div>
        <div className="public-hero-art" aria-label="A welcoming school community" role="img">
          <div className="public-art-card public-art-card-main">
            <span className="public-art-eyebrow">THE CONNECTION CONTINUES</span>
            <strong>Meet where<br />your story began.</strong>
            <span className="public-art-line" />
            <small>People · memories · possibilities</small>
          </div>
          <div className="public-art-note">EST. 1958 <span>✦</span></div>
          <div className="public-art-stamp">AM</div>
        </div>
      </section>

      <section className="public-community" id="community">
        <div>
          <p className="public-kicker">ONE COMMUNITY, MANY STORIES</p>
          <h2>There is always<br /><em>more to remember.</em></h2>
        </div>
        <div className="public-community-copy">
          <p>Alumni Meet brings your school community into one thoughtful, welcoming space. Find familiar faces, share your next milestone, and make room for the connections still ahead.</p>
          <div className="public-metrics"><span><strong>01</strong><small>Find your people</small></span><span><strong>02</strong><small>Join the moment</small></span><span><strong>03</strong><small>Stay connected</small></span></div>
        </div>
      </section>
    </main>
  );
}
